read_stock_and_suppliers.source:
async function run(input, tools) {
  const settings = (input && input.settings) || {};
  const rules = (input && input.rules) || {};
  const maxDays = Number(rules.max_delivery_days ?? settings.max_delivery_days);
  const ordersToPlace = [];

  let stockRows = [];
  try {
    const res = await tools.sheets.read({ sheet: settings.stock_sheet });
    stockRows = (res && res.rows) || [];
  } catch (e) {
    return { orders_to_place: [] };
  }

  const low = stockRows.filter(r => {
    const m = Number(r.metres);
    const min = Number(r.minimum);
    return !isNaN(m) && !isNaN(min) && m < min;
  });
  if (!low.length || !settings.suppliers_page) {
    return { orders_to_place: [] };
  }

  let offers = [];
  try {
    const page = await tools.web.fetch({ url: settings.suppliers_page });
    const text = (page && page.text) || '';
    const lines = String(text).split(/\r?\n/);
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;
      const parts = line.split('|').map(p => p.trim());
      if (parts.length < 4) continue;
      const [supplier, fabric, priceStr, daysStr] = parts;
      const price = Number(priceStr);
      const days = Number(daysStr);
      if (!supplier || !fabric || isNaN(price) || isNaN(days)) continue;
      offers.push({ supplier, fabric, price, days });
    }
  } catch (e) {
    return { orders_to_place: [] };
  }

  for (const row of low) {
    const fabric = String(row.fabric);
    const metres = Number(row.metres);
    const minimum = Number(row.minimum);
    const need = minimum - metres;
    if (!(need > 0)) continue;

    const candidates = offers.filter(o =>
      o.fabric.toLowerCase() === fabric.toLowerCase() &&
      (isNaN(maxDays) || o.days <= maxDays)
    );
    if (!candidates.length) continue;
    candidates.sort((a, b) => a.price - b.price);
    const best = candidates[0];

    ordersToPlace.push({
      fabric,
      supplier: best.supplier,
      metres_to_order: Math.round(need * 100) / 100,
      total_cost_usdc: Math.round(best.price * need * 100) / 100
    });
  }

  return { orders_to_place: ordersToPlace };
}

