async function run(input, tools) {
  const settings = input.settings || {};
  const orders = input.orders_to_place;
  const rows = Array.isArray(orders) ? orders : [];
  return {
    write_orders_arg: {
      sheet: settings.orders_sheet,
      rows: rows
    }
  };
}

prepare_memory_arg.source:
async function run(input) {
  const orders = Array.isArray(input && input.orders_to_place) ? input.orders_to_place : [];
  const now = new Date().toISOString();
  const value = { placed_at: now, lines: orders };
  return { memory_arg: { key: 'last_order', value } };
}
